package app.velyntora.windows.effects;
import art.velyntora.core.DrawingView;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.concurrent.Callable;
import java.util.function.Consumer;
import app.velyntora.windows.canvas.CanvasPanel;
public final class EffectsLibrary {
 private static int[] values(Component owner,String title,String[] labels,int[] min,int[] max,int[] initial){JPanel form=new JPanel(new GridLayout(0,2,8,6));JSpinner[] inputs=new JSpinner[labels.length];for(int i=0;i<labels.length;i++){form.add(new JLabel(labels[i]));inputs[i]=new JSpinner(new SpinnerNumberModel(initial[i],min[i],max[i],1));form.add(inputs[i]);}JScrollPane scroll=new JScrollPane(form);scroll.setPreferredSize(new Dimension(470,Math.min(550,45*labels.length)));if(JOptionPane.showConfirmDialog(owner,scroll,title,JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return null;int[] result=new int[inputs.length];for(int i=0;i<inputs.length;i++)result[i]=(int)inputs[i].getValue();return result;}
 public static JMenu create(JFrame owner,CanvasPanel canvas,Consumer<Callable<Boolean>> execute){JMenu all=new JMenu("Todos los efectos");
  String[][] names={{"Desenfoque de caja","Enfocar","Detectar bordes","Repujado","Pixelar","Ruido","Viñeta"},{"Gaussiano","Movimiento","Radial","Zoom"},{"Remolino","Abombar / pellizcar","Ondas radiales","Cristales","Escarcha"},{"Pintura al óleo","Boceto a lápiz","Boceto a tinta","Resplandor","Retrato suave","Mediana / percentil","Reducir ojos rojos"},{"Nubes","Voronoi","Celdas","Mandelbrot","Julia"},{"Fragmentar","Desenfoque de lente","Abolladuras","Inversión polar","Reducir ruido","Contorno de bordes","Relieve direccional","Tramado ordenado"},{"Alinear objeto","Suavizar borde alfa","Contorno de objeto"}};String[] groups={"Básicos","Desenfoques","Distorsiones","Arte y fotografía","Generadores","Más filtros","Objetos"};
  for(int group=0;group<groups.length;group++){JMenu menu=new JMenu(groups[group]);for(int kind=0;kind<names[group].length;kind++){final int g=group,k=kind;JMenuItem item=new JMenuItem(names[g][k]);item.addActionListener(e->{int[] v;switch(g){
   case 0:v=values(owner,names[g][k],new String[]{"Intensidad"},new int[]{1},new int[]{100},new int[]{8});if(v!=null)execute.accept(()->DrawingView.nativeEffect(k,v[0]));break;
   case 1:v=values(owner,names[g][k],new String[]{"Radio / intensidad","Dirección (°)","Centro X (%)","Centro Y (%)"},new int[]{0,-180,0,0},new int[]{k==0?32:k==2?45:100,180,100,100},new int[]{3,0,50,50});if(v!=null)execute.accept(()->DrawingView.nativeBlur(k,v[0],v[1],v[2],v[3]));break;
   case 2:v=values(owner,names[g][k],new String[]{"Intensidad / giro","Radio / periodo","Dirección","Centro X (%)","Centro Y (%)"},new int[]{k==0?-180:k==4?0:-100,1,-180,0,0},new int[]{k==0?180:100,100,180,100,100},new int[]{40,50,0,50,50});if(v!=null)execute.accept(()->DrawingView.nativeDistortion(k,v[0],v[1],v[2],v[3],v[4]));break;
   case 3:v=values(owner,names[g][k],new String[]{"Intensidad / percentil / niveles","Radio","Umbral"},new int[]{k==0?2:0,1,0},new int[]{k==0?32:100,k==0?8:k==5?4:16,255},new int[]{k==0?8:k==5?50:100,2,80});if(v!=null)execute.accept(()->DrawingView.nativeArtistic(k,v[0],v[1],v[2]));break;
   case 4:v=values(owner,names[g][k],new String[]{"Escala / zoom","Detalle / octavas / iteraciones","Semilla"},new int[]{1,1,0},new int[]{k<3?512:100,k==0?8:128,10000},new int[]{k<3?64:1,k==0?5:48,0});if(v!=null)execute.accept(()->DrawingView.nativeRender(k,v[0],v[1],v[2],canvas.color,canvas.secondary));break;
   case 5:v=values(owner,names[g][k],new String[]{"Intensidad / distancia","Radio / escala / niveles","Dirección / semilla / tolerancia"},new int[]{0,k==0||k==7?2:1,k==0||k==6?-180:0},new int[]{k==0?64:k==1?32:100,k==0||k==7?16:k==2?128:k==3?100:k==4?3:8,k==0||k==6?180:k==2?10000:255},new int[]{k<=1?4:100,k==0||k==7?4:k==2?32:k==3?100:2,k==4?60:0});if(v!=null)execute.accept(()->DrawingView.nativeUtility(k,v[0],v[1],v[2]));break;
   default:v=values(owner,names[g][k],new String[]{k==0?"Posición 0–8":"Radio","Tolerancia alfa","Opción suave / borde (0/1)"},new int[]{0,0,0},new int[]{k==0?8:64,255,1},new int[]{k==0?4:6,20,0});if(v!=null)execute.accept(()->DrawingView.nativeObject(k,v[0],v[1],canvas.color,v[2]!=0));
  }});menu.add(item);}all.add(menu);}
  JMenu color=new JMenu("Ajustes de color completos");add(color,"Curvas",()->curves(owner,execute));add(color,"Niveles RGB por canal",()->{String[] label=new String[15];int[] lo=new int[15],hi=new int[15],initial=new int[15];String[] channels={"Rojo","Verde","Azul"},fields={"Negro entrada","Blanco entrada","Gamma (%)","Negro salida","Blanco salida"};for(int i=0;i<15;i++){label[i]=channels[i/5]+" · "+fields[i%5];lo[i]=i%5==2?10:0;hi[i]=i%5==2?300:255;initial[i]=new int[]{0,255,100,0,255}[i%5];}int[] v=values(owner,"Niveles RGB",label,lo,hi,initial);if(v!=null)execute.accept(()->DrawingView.nativeColorAdjustment(1,v));});
  add(color,"Niveles automáticos",()->{int[] v=values(owner,"Niveles automáticos",new String[]{"Recorte por extremo (‰)"},new int[]{0},new int[]{50},new int[]{5});if(v!=null)execute.accept(()->DrawingView.nativeColorAdjustment(2,v));});
  add(color,"Posterización RGB",()->{int[] v=values(owner,"Posterización RGB",new String[]{"Rojo","Verde","Azul"},new int[]{2,2,2},new int[]{256,256,256},new int[]{4,4,4});if(v!=null)execute.accept(()->DrawingView.nativeColorAdjustment(3,v));});
  add(color,"Tono / saturación / luminosidad",()->{int[] v=values(owner,"Tono / saturación / luminosidad",new String[]{"Tono","Saturación (%)","Luminosidad (%)"},new int[]{-180,0,-100},new int[]{180,200,100},new int[]{0,100,0});if(v!=null)execute.accept(()->DrawingView.nativeColorAdjustment(4,v));});all.add(color);return all;
 }
 private static void add(JMenu menu,String name,Runnable action){JMenuItem item=new JMenuItem(name);item.addActionListener(e->action.run());menu.add(item);}
 private static void curves(JFrame owner,Consumer<Callable<Boolean>> execute){TreeMap<Integer,Integer> points=new TreeMap<>();points.put(0,0);points.put(255,255);JPanel graph=new JPanel(){int selected=-1;{setPreferredSize(new Dimension(400,300));MouseAdapter mouse=new MouseAdapter(){private void update(MouseEvent e){int x=Math.max(0,Math.min(255,e.getX()*255/Math.max(1,getWidth()-1))),y=Math.max(0,Math.min(255,255-e.getY()*255/Math.max(1,getHeight()-1)));if(SwingUtilities.isRightMouseButton(e)){if(x>0&&x<255)points.remove(points.floorKey(x));}else{if(selected>0&&selected<255)points.remove(selected);points.put(x,y);selected=x;}repaint();}public void mousePressed(MouseEvent e){selected=-1;update(e);}public void mouseDragged(MouseEvent e){update(e);}};addMouseListener(mouse);addMouseMotionListener(mouse);}@Override protected void paintComponent(Graphics gr){super.paintComponent(gr);Graphics2D g=(Graphics2D)gr;g.setColor(Color.LIGHT_GRAY);for(int i=0;i<=4;i++){g.drawLine(i*getWidth()/4,0,i*getWidth()/4,getHeight());g.drawLine(0,i*getHeight()/4,getWidth(),i*getHeight()/4);}g.setColor(Color.MAGENTA);Point previous=null;for(var p:points.entrySet()){Point now=new Point(p.getKey()*getWidth()/255,(255-p.getValue())*getHeight()/255);if(previous!=null)g.drawLine(previous.x,previous.y,now.x,now.y);g.fillOval(now.x-4,now.y-4,8,8);previous=now;}}};JComboBox<String> channel=new JComboBox<>(new String[]{"RGB","Rojo","Verde","Azul","Luminosidad"});JPanel panel=new JPanel(new BorderLayout());panel.add(channel,BorderLayout.NORTH);panel.add(graph);if(JOptionPane.showConfirmDialog(owner,panel,"Curvas · clic y arrastra; clic derecho elimina",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){int[] v=new int[257];for(int x=0;x<256;x++){var a=points.floorEntry(x);var b=points.ceilingEntry(x);if(a==null)a=points.firstEntry();if(b==null)b=points.lastEntry();v[x]=a.getKey().equals(b.getKey())?a.getValue():(int)Math.round(a.getValue()+(b.getValue()-a.getValue())*(x-a.getKey())/(double)(b.getKey()-a.getKey()));}v[256]=channel.getSelectedIndex();execute.accept(()->DrawingView.nativeColorAdjustment(0,v));}}
}
